'use strict';const elementToggleFunc=function(elem){elem.classList.toggle("active");}
const sidebar=document.querySelector("[data-sidebar]");const sidebarBtn=document.querySelector("[data-sidebar-btn]");if(sidebar&&sidebarBtn){sidebarBtn.addEventListener("click",function(){elementToggleFunc(sidebar);});}
const testimonialsItem=document.querySelectorAll("[data-testimonials-item]");const modalContainer=document.querySelector("[data-modal-container]");const modalCloseBtn=document.querySelector("[data-modal-close-btn]");const overlay=document.querySelector("[data-overlay]");if(modalContainer&&modalCloseBtn&&overlay){const modalImg=document.querySelector("[data-modal-img]");const modalTitle=document.querySelector("[data-modal-title]");const modalText=document.querySelector("[data-modal-text]");const testimonialsModalFunc=function(){modalContainer.classList.toggle("active");overlay.classList.toggle("active");}
testimonialsItem.forEach(item=>{item.addEventListener("click",function(){modalImg.src=this.querySelector("[data-testimonials-avatar]").src;modalImg.alt=this.querySelector("[data-testimonials-avatar]").alt;modalTitle.innerHTML=this.querySelector("[data-testimonials-title]").innerHTML;modalText.innerHTML=this.querySelector("[data-testimonials-text]").innerHTML;testimonialsModalFunc();});});modalCloseBtn.addEventListener("click",testimonialsModalFunc);overlay.addEventListener("click",testimonialsModalFunc);}
const form=document.querySelector("[data-form]");const formInputs=document.querySelectorAll("[data-form-input]");const formBtn=document.querySelector("[data-form-btn]");if(form&&formInputs.length>0&&formBtn){formInputs.forEach(input=>{input.addEventListener("input",function(){if(form.checkValidity()){formBtn.removeAttribute("disabled");}else{formBtn.setAttribute("disabled","");}});});}
const initTypewriter=()=>{const titleElement=document.querySelector('.info-content .title');if(!titleElement)return;const roles=["Data Scientist","Python Developer","Problem Solver","Analyst"];let roleIndex=0;let charIndex=0;let isDeleting=false;let typeSpeed=100;titleElement.classList.add('typewriter-cursor');function type(){const currentRole=roles[roleIndex];if(isDeleting){titleElement.textContent=currentRole.substring(0,charIndex-1);charIndex--;typeSpeed=50;}else{titleElement.textContent=currentRole.substring(0,charIndex+1);charIndex++;typeSpeed=150;}
if(!isDeleting&&charIndex===currentRole.length){isDeleting=true;typeSpeed=2000;}else if(isDeleting&&charIndex===0){isDeleting=false;roleIndex=(roleIndex+1)%roles.length;typeSpeed=500;}
setTimeout(type,typeSpeed);}
type();};const initTiltEffect=()=>{const cards=document.querySelectorAll('.project-item, .certification-item, .events-post-item');cards.forEach(card=>{card.classList.add('tilt-effect');card.addEventListener('mousemove',(e)=>{const rect=card.getBoundingClientRect();const x=e.clientX-rect.left;const y=e.clientY-rect.top;const centerX=rect.width/2;const centerY=rect.height/2;const rotateX=((y-centerY)/centerY)*-5;const rotateY=((x-centerX)/centerX)*5;card.style.transform=`perspective(1000px)rotateX(${rotateX}deg)rotateY(${rotateY}deg)scale3d(1.02,1.02,1.02)`;});card.addEventListener('mouseleave',()=>{card.style.transform='perspective(1000px) rotateX(0) rotateY(0) scale3d(1, 1, 1)';});});};document.addEventListener('DOMContentLoaded',()=>{initTypewriter();initTiltEffect();const initializeCategoryFilter=()=>{const filterItems=document.querySelectorAll("[data-filter-item]");if(filterItems.length===0)return;const counts={all:filterItems.length};filterItems.forEach(item=>{const cat=(item.dataset.category||'').toLowerCase();if(cat)counts[cat]=(counts[cat]||0)+1;});const filterBtns=document.querySelectorAll("[data-filter-btn]");filterBtns.forEach(btn=>{const baseText=btn.innerText.replace(/\s*\(\d+\)$/,'').trim();const cat=baseText.toLowerCase();if(counts[cat]!==undefined){btn.innerHTML=`${baseText}<span class="count-pill">${counts[cat]}</span>`;}});const selectItems=document.querySelectorAll("[data-select-item]");selectItems.forEach(item=>{const baseText=item.innerText.replace(/\s*\(\d+\)$/,'').trim();const cat=baseText.toLowerCase();if(counts[cat]!==undefined){item.innerHTML=`${baseText}<span class="count-pill">${counts[cat]}</span>`;}});const select=document.querySelector("[data-select]");const selectValue=document.querySelector("[data-selecct-value]");const filterFunc=function(selectedValue){for(let i=0;i<filterItems.length;i++){if(selectedValue==="all"||selectedValue===(filterItems[i].dataset.category||'').toLowerCase()){filterItems[i].classList.add("active");}else{filterItems[i].classList.remove("active");}}};let lastClickedBtn=filterBtns.length>0?filterBtns[0]:null;if(lastClickedBtn){for(let i=0;i<filterBtns.length;i++){filterBtns[i].addEventListener("click",function(){const selectedValue=this.childNodes[0].nodeValue.trim().toLowerCase();if(selectValue)selectValue.innerHTML=this.innerHTML;filterFunc(selectedValue);lastClickedBtn.classList.remove("active");this.classList.add("active");lastClickedBtn=this;});}}
if(select){select.addEventListener("click",function(){elementToggleFunc(this);});for(let i=0;i<selectItems.length;i++){selectItems[i].addEventListener("click",function(){const selectedCat=this.childNodes[0].nodeValue.trim().toLowerCase();if(selectValue){selectValue.innerHTML=this.innerHTML;}
elementToggleFunc(select);filterFunc(selectedCat);});}}};initializeCategoryFilter();const yearElement=document.getElementById('current-year');if(yearElement){yearElement.textContent=new Date().getFullYear();}
const themeBtns=document.querySelectorAll("[data-theme-btn]");if(themeBtns.length>0){const applyTheme=(theme)=>{const isLight=theme==="light";if(isLight){document.body.setAttribute("data-theme","light");}else{document.body.removeAttribute("data-theme");}
localStorage.setItem("theme",theme);themeBtns.forEach(btn=>btn.setAttribute("aria-pressed",isLight));document.querySelectorAll('.theme-aware-img').forEach(img=>{if(isLight&&img.hasAttribute('data-light-src')){img.src=img.getAttribute('data-light-src');}else if(!isLight&&img.hasAttribute('data-dark-src')){img.src=img.getAttribute('data-dark-src');}});};const currentTheme=localStorage.getItem("theme")||"dark";applyTheme(currentTheme);themeBtns.forEach(btn=>{btn.addEventListener("click",function(){const isLight=document.body.getAttribute("data-theme")==="light";applyTheme(isLight?"dark":"light");});});}
document.addEventListener("keydown",function(e){const tag=e.target.tagName;const isEditable=e.target.isContentEditable;if(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||tag==="BUTTON"||tag==="A"||isEditable)return;if((e.key==="m"||e.key==="M")&&!e.ctrlKey&&!e.metaKey){const themeBtn=document.querySelector("[data-theme-btn]");if(themeBtn)themeBtn.click();}
if(!e.ctrlKey&&!e.metaKey&&!e.altKey){const navLinks=["/","/projects/","/certifications/","/events/","/blogs/","/contact/"];const num=parseInt(e.key);if(num>=1&&num<=6){window.location.href=navLinks[num-1];}}});});